);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES (
  $LEGAL_74edd796ad0f86$doc_motor_vehicles_and_transport_management_act_2049$LEGAL_74edd796ad0f86$,
  $LEGAL_74edd796ad0f86$Vehicle & Transportation Act, 2049$LEGAL_74edd796ad0f86$,
